// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** Someone who may write in the medical record (MSDS IMS 145, 147). */
export interface AuthorizedPersonOut {
  user_id: number;
  employee_id: number | null;
  name: string;
  designation: string | null;
  specialty: string | null;
  department_name: string | null;
  staff_category: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting" | null;
  clinical: boolean;
  /** e.g. PMDC 12345-P; null: none on file (shown in red for a clinician) */
  registration: string | null;
  /** The roles that let them write */
  roles: string[];
  /** The parts of the record they may write */
  writes: string[];
  /** A specimen of their digital stamp as it prints under their entries */
  stamp: string | null;
}

/** Who may write in the medical record (MSDS IMS 145) — GET /api/v1/msds/authorized-personnel (who may call: holders of msds.view or msds.inspect). */
export function authorizedPersonnel(): Promise<AuthorizedPersonOut[]> {
  return api<AuthorizedPersonOut[]>("GET", `/msds/authorized-personnel`, undefined);
}

/** One inspection document (PDF) — GET /api/v1/msds/inspection-pack/documents/{key}/pdf (who may call: holders of msds.view or msds.inspect). */
export function documentPdfMsdsInspectionPackDocuments(key: string, query?: { category?: "Clinic" | "IIC" | "IIB" | "IIA" | "I" | null; date_from?: string | null; date_to?: string | null }): Promise<unknown> {
  return api<unknown>("GET", withQuery(`/msds/inspection-pack/documents/${key}/pdf`, query), undefined);
}
